package wgmodern;
import java.util.*;import net.minecraft.core.*;import net.minecraft.core.registries.Registries;import net.minecraft.resources.*;import net.minecraft.nbt.*;import net.minecraft.server.level.ServerLevel;import net.minecraft.network.protocol.game.ClientboundBlockEntityDataPacket;import net.minecraft.world.item.*;import net.minecraft.world.level.*;import net.minecraft.world.level.biome.Biome;import net.minecraft.world.level.block.*;import net.minecraft.world.level.block.entity.*;import net.minecraft.world.level.block.state.BlockState;import net.minecraft.world.phys.shapes.*;import net.minecraftforge.registries.*;import tc4revival.aspect.*;import tc4revival.content.*;import witchinggadgets.api.ITerraformFocus;
public class Terraformer extends BaseEntityBlock {
 public record FocusDefinition(String aspect,String biome,String display,String legacy){}
 public static final Map<String,FocusDefinition> DEFINITIONS=new LinkedHashMap<>();public static final Map<String,RegistryObject<Block>> FOCI=new LinkedHashMap<>();public static final Map<String,RegistryObject<Item>> ITEMS=new LinkedHashMap<>();
 static{DEFINITIONS.put("plains",new FocusDefinition("herba","minecraft:plains","minecraft:grass_block","Plains"));DEFINITIONS.put("cold_taiga",new FocusDefinition("gelum","minecraft:snowy_taiga","minecraft:ice","ColdTaiga"));DEFINITIONS.put("desert",new FocusDefinition("ignis","minecraft:desert","minecraft:sand","Desert"));DEFINITIONS.put("jungle",new FocusDefinition("arbor","minecraft:jungle","minecraft:jungle_log","Jungle"));DEFINITIONS.put("hell",new FocusDefinition("tenebrae","minecraft:nether_wastes","minecraft:nether_bricks","Hell"));DEFINITIONS.put("taint",new FocusDefinition("vitium","thaumcraft:tainted_land","thaumcraft:taint_crust","Taint"));DEFINITIONS.put("mushroom",new FocusDefinition("limus","minecraft:mushroom_fields","minecraft:mycelium","Mushroom"));}
 public static void register(){DEFINITIONS.forEach((name,definition)->{String id="terraform_focus_"+name;RegistryObject<Block> block=Content.BLOCKS.register(id,()->new Focus(name,definition));FOCI.put(name,block);ITEMS.put(name,Content.ITEMS.register(id,()->new RenderedItem(block.get())));});thaumcraft.api.ThaumcraftApi.addWarpToItem(new ResourceLocation("witchinggadgets","terraform_focus_hell"),1);thaumcraft.api.ThaumcraftApi.addWarpToItem(new ResourceLocation("witchinggadgets","terraform_focus_taint"),2);}
 public Terraformer(){super(Properties.copy(Blocks.IRON_BLOCK).strength(4,9).noOcclusion().isValidSpawn((s,l,p,t)->false));}
 @Override public String getDescriptionId(){return "tile.WG_MetalDevice.terraformer";}@Override public RenderShape getRenderShape(BlockState s){return RenderShape.ENTITYBLOCK_ANIMATED;}@Override public BlockEntity newBlockEntity(BlockPos p,BlockState s){return new Tile(p,s);}
 @Override public <T extends BlockEntity> BlockEntityTicker<T> getTicker(Level l,BlockState s,BlockEntityType<T> t){return l.isClientSide?null:createTickerHelper(t,Content.TERRAFORMER_TILE.get(),Tile::tick);}
 public static ITerraformFocus focus(Level l,BlockPos p){var be=l.getBlockEntity(p);return be instanceof ITerraformFocus f?f:l.getBlockState(p).getBlock() instanceof ITerraformFocus f?f:null;}
 public static class Focus extends BaseEntityBlock implements ITerraformFocus {
  public final String name;public final FocusDefinition definition;public Focus(String name,FocusDefinition definition){super(Properties.copy(Blocks.IRON_BLOCK).strength(4,9).noOcclusion().isValidSpawn((s,l,p,t)->false));this.name=name;this.definition=definition;}
  @Override public String getDescriptionId(){return "tile.WG_MetalDevice.tfFocus"+definition.legacy();}@Override public RenderShape getRenderShape(BlockState s){return RenderShape.ENTITYBLOCK_ANIMATED;}@Override public BlockEntity newBlockEntity(BlockPos p,BlockState s){return new FocusTile(p,s);}
  @Override public VoxelShape getShape(BlockState s,BlockGetter l,BlockPos p,CollisionContext c){return name.equals("taint")||name.equals("mushroom")?Shapes.block():Block.box(2,0,2,14,12,14);}
  @Override public Aspect requiredAspect(Level l,BlockPos p){return TCAspects.catalog().require(definition.aspect());}@Override public ResourceKey<Biome> createdBiome(Level l,BlockPos p){return ResourceKey.create(Registries.BIOME,new ResourceLocation(definition.biome()));}@Override public ItemStack displayedBlock(Level l,BlockPos p){return new ItemStack(ForgeRegistries.ITEMS.getValue(new ResourceLocation(definition.display())));}
 }
 public static class FocusTile extends BlockEntity {public FocusTile(BlockPos p,BlockState s){super(Content.TERRAFORM_FOCUS_TILE.get(),p,s);}}
 public static class RenderedItem extends BlockItem {public RenderedItem(Block b){super(b,new Item.Properties());}@Override public void initializeClient(java.util.function.Consumer<net.minecraftforge.client.extensions.common.IClientItemExtensions> c){c.accept(new net.minecraftforge.client.extensions.common.IClientItemExtensions(){public net.minecraft.client.renderer.BlockEntityWithoutLevelRenderer getCustomRenderer(){return TerraformRenderer.ItemRenderer.instance();}});}}
 public static class Tile extends BlockEntity implements thaumcraft.api.aspects.IAspectContainer,thaumcraft.api.aspects.IEssentiaTransport {
  public AspectAmounts stored=new AspectAmounts();public int ticks,drawDelay;
  public Tile(BlockPos p,BlockState s){super(Content.TERRAFORMER_TILE.get(),p,s);}
  public Aspect required(){if(level==null)return null;var f=focus(level,worldPosition.above());return f==null?null:f.requiredAspect(level,worldPosition.above());}
  public static void tick(Level l,BlockPos p,BlockState s,Tile t){t.ticks++;var f=focus(l,p.above());var a=t.required();if(f!=null&&a!=null){if(++t.drawDelay%5==0&&l.hasChunkAt(p.below())&&l.getBlockEntity(p.below()) instanceof EssentiaTransport source&&source.connectable(Direction.UP)&&source.canOutput(Direction.UP)&&source.suction(Direction.UP)<t.suction(Direction.DOWN)&&source.takeEssentia(a,1,Direction.UP)==1)t.addToContainer(a,1);if(t.ticks>=20&&t.stored.amount(a)>=4){var biome=f.createdBiome(l,p.above());if(biome!=null&&l.registryAccess().registryOrThrow(Registries.BIOME).getHolder(biome).isPresent()){BlockPos target=null;for(int attempt=0;attempt<=40;attempt++){var q=p.offset(l.random.nextInt(16)-l.random.nextInt(16),0,l.random.nextInt(16)-l.random.nextInt(16));if(!l.hasChunkAt(q)||!l.getWorldBorder().isWithinBounds(q))continue;if(!l.getBiomeManager().getNoiseBiomeAtPosition(q).is(biome)){target=q;break;}}if(target!=null)t.transform((ServerLevel)l,target,biome,a);}}}if(t.ticks>=20)t.ticks=0;}
  public boolean transform(ServerLevel l,BlockPos target,ResourceKey<Biome> biome,Aspect aspect){if(stored.amount(aspect)<4||!l.hasChunkAt(target)||!l.getWorldBorder().isWithinBounds(target)||l.getBiomeManager().getNoiseBiomeAtPosition(target).is(biome))return false;if(thaumcraft.api.visnet.VisNetHandler.drainVis(l,worldPosition,thaumcraft.api.aspects.Aspect.EARTH,4)!=4)return false;if(!WorldBiomeChanges.changeColumn(l,target,biome))return false;takeFromContainer(aspect,4);l.blockEvent(worldPosition,getBlockState().getBlock(),1,aspect.color());return true;}
  @Override public boolean triggerEvent(int id,int data){if(id==1){/* The server must accept the event before it is broadcast to clients. */if(level!=null&&level.isClientSide)net.minecraftforge.fml.DistExecutor.unsafeRunWhenOn(net.minecraftforge.api.distmarker.Dist.CLIENT,()->()->TerraformRenderer.vent(worldPosition,data));return true;}return super.triggerEvent(id,data);}
  @Override public thaumcraft.api.aspects.AspectList getAspects(){return thaumcraft.api.aspects.AspectList.from(stored);}@Override public void setAspects(thaumcraft.api.aspects.AspectList values){stored=values.unwrap();changed();}@Override public boolean accepts(Aspect a){return a!=null&&a.equals(required());}@Override public int capacity(Aspect a){return Integer.MAX_VALUE;}
  public void changed(){setChanged();if(level!=null&&!level.isClientSide)level.sendBlockUpdated(worldPosition,getBlockState(),getBlockState(),2);}
  @Override public boolean connectable(Direction f){return f==Direction.DOWN;}@Override public boolean canInput(Direction f){return f==Direction.DOWN;}@Override public boolean canOutput(Direction f){return false;}@Override public int suction(Direction f){return required()!=null?128:0;}@Override public Aspect suctionType(Direction f){return required();}@Override public int minimumSuction(){return 0;}@Override public Aspect essentiaType(Direction f){return null;}@Override public int essentiaAmount(Direction f){return 0;}@Override public int takeEssentia(Aspect a,int n,Direction f){return 0;}@Override public int addEssentia(Aspect a,int n,Direction f){return n>0&&canInput(f)?n-addToContainer(a,n):0;}
  @Override protected void saveAdditional(CompoundTag t){super.saveAdditional(t);AspectNbt.write(t,stored);t.putInt("tick",ticks);}@Override public void load(CompoundTag t){super.load(t);stored=AspectNbt.read(t,TCAspects.catalog()).amounts();ticks=Math.floorMod(t.getInt("tick"),20);}@Override public CompoundTag getUpdateTag(){return saveWithoutMetadata();}@Override public ClientboundBlockEntityDataPacket getUpdatePacket(){return ClientboundBlockEntityDataPacket.create(this);}
 }
}
